<?php
declare(strict_types=1);

final class Shifts
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function uuid(mixed $id):bool{return is_string($id)&&(bool)preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$id);}
    private static function text(mixed $text,int $max,bool $required=true):string{if(!is_string($text))throw new HttpError(400,'Nội dung ca không hợp lệ.');$text=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$text);if($text===null||$required&&$text===''||strlen(mb_convert_encoding($text,'UTF-16LE','UTF-8'))/2>$max)throw new HttpError(400,'Kiểm tra lý do và mã chứng từ.');return $text;}
    private static function money(mixed $v):int{if(!is_int($v)||$v<0||$v>15000000000)throw new HttpError(400,'Số tiền phải là số nguyên từ 0 đến 15 tỷ.');return $v;}
    private static function safe(mixed $v):int{if(is_string($v)&&preg_match('/^[0-9]+$/D',$v)&&strlen($v)<=16)$v=(int)$v;if(!is_int($v)||$v<0||$v>9007199254740991)throw new HttpError(409,'Tổng tiền ca vượt phạm vi xử lý.');return $v;}
    private static function hash(array $body):string{return hash('sha256',json_encode($body,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_LINE_TERMINATORS|JSON_THROW_ON_ERROR));}
    private static function actorName(array $actor):string{return $actor['email'] ?? 'Quản trị';}
    private static function time(?string $date):?string{return $date===null?null:str_replace(' ','T',$date).'Z';}
    private function audit(array $actor,string $action,string $id):void{$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor['id'],$action,$id]);}
    private function receipts(string $id):array{$rows=$this->query('SELECT p.id,p.amount,p.method,p.admin_id,p.created_at,r.reference,o.code FROM jingo_pos_shift_receipts s JOIN jingo_order_payments p ON p.id=s.payment_id JOIN jingo_payment_references r ON r.reference_hash=p.reference_hash JOIN jingo_orders o ON o.id=p.order_id WHERE s.shift_id=? ORDER BY p.created_at,p.id',[$id])->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['amount']=self::safe($r['amount']);if(!in_array($r['method'],['CASH','BANK'],true))throw new HttpError(409,'Phương thức thu chưa được hỗ trợ trong ca.');$r['created_at']=self::time($r['created_at']);}unset($r);return $rows;}
    private function movements(string $id):array{$rows=$this->query('SELECT id,kind,amount,reference,note,actor_id,actor_name,created_at FROM jingo_pos_cash_movements WHERE shift_id=? ORDER BY created_at,id',[$id])->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['amount']=self::safe($r['amount']);if(!in_array($r['kind'],['IN','OUT'],true)||$r['amount']===0)throw new HttpError(409,'Dữ liệu thu chi ca không hợp lệ.');$r['created_at']=self::time($r['created_at']);}unset($r);return $rows;}
    private static function totals(int $opening,array $receipts,array $movements):array
    {
        $values=['cashIn'=>0,'cashOut'=>0,'cash'=>0,'bank'=>0];foreach($receipts as $r){$key=$r['method']==='CASH'?'cash':'bank';$values[$key]=self::safe($values[$key]+$r['amount']);}foreach($movements as $m){$key=$m['kind']==='IN'?'cashIn':'cashOut';$values[$key]=self::safe($values[$key]+$m['amount']);}$values['expectedCash']=self::safe($opening+$values['cash']+$values['cashIn']-$values['cashOut']);$values['movementCount']=count($movements);$values['receiptCount']=count($receipts);return $values;
    }
    public function list(array $input):array
    {
        if(array_diff(array_keys($input),['counterId'])||!is_string($input['counterId'] ?? null)||!preg_match('/^[a-zA-Z0-9_-]{1,80}$/D',$input['counterId']))throw new HttpError(400,'Chọn quầy hợp lệ.');if(!$this->query('SELECT id FROM jingo_counters WHERE id=?',[$input['counterId']])->fetchColumn())throw new HttpError(404,'Không tìm thấy quầy.');$items=[];foreach($this->query('SELECT id,counter_name,opened_name,opening_cash,opened_at,closed_at,summary,version FROM jingo_pos_shifts WHERE counter_id=? ORDER BY opened_at DESC,id DESC LIMIT 50',[$input['counterId']])->fetchAll(PDO::FETCH_ASSOC) as $row)$items[]=['id'=>$row['id'],'counterName'=>$row['counter_name'],'openedName'=>$row['opened_name'],'openingCash'=>self::safe($row['opening_cash']),'openedAt'=>self::time($row['opened_at']),'closedAt'=>self::time($row['closed_at']),'summary'=>$row['summary']===null?null:json_decode($row['summary'],true,512,JSON_THROW_ON_ERROR),'version'=>(int)$row['version']];return ['data'=>$items];
    }
    public function detail(string $id):array
    {
        if(!self::uuid($id))throw new HttpError(400,'Mã ca không hợp lệ.');$this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{$row=$this->query('SELECT * FROM jingo_pos_shifts WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy ca.');$receipts=$this->receipts($id);$movements=$this->movements($id);$opening=self::safe($row['opening_cash']);$summary=$row['summary']===null?self::totals($opening,$receipts,$movements):json_decode($row['summary'],true,512,JSON_THROW_ON_ERROR);$this->db->commit();return ['id'=>$id,'counterId'=>$row['counter_id'],'counterName'=>$row['counter_name'],'openedBy'=>$row['opened_by'],'openedName'=>$row['opened_name'],'openingCash'=>$opening,'openingNote'=>$row['opening_note'],'openedAt'=>self::time($row['opened_at']),'closedAt'=>self::time($row['closed_at']),'closedBy'=>$row['closed_by'],'closeNote'=>$row['close_note'],'version'=>(int)$row['version'],'summary'=>$summary,'receipts'=>$receipts,'movements'=>$movements,'canManageCash'=>$row['closed_at']===null,'canClose'=>$row['closed_at']===null];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function open(array $input,array $actor):array
    {
        if(array_diff(array_keys($input),['requestId','counterId','openingCash','note'])||!self::uuid($input['requestId'] ?? null)||!is_string($input['counterId'] ?? null)||!preg_match('/^[a-zA-Z0-9_-]{1,80}$/D',$input['counterId']))throw new HttpError(400,'Kiểm tra quầy và mã mở ca.');$input=['requestId'=>$input['requestId'],'counterId'=>$input['counterId'],'openingCash'=>self::money($input['openingCash'] ?? null),'note'=>self::text(array_key_exists('note',$input)?$input['note']:'',1000,false)];$hash=self::hash(['actor'=>$actor['id'],'input'=>$input]);$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$counter=$this->query('SELECT data FROM jingo_counters WHERE id=? FOR UPDATE',[$input['counterId']])->fetchColumn();if($counter===false)throw new HttpError(404,'Không tìm thấy quầy.');$prior=$this->query('SELECT open_hash FROM jingo_pos_shifts WHERE id=?',[$input['requestId']])->fetchColumn();if($prior!==false){if(!hash_equals($prior,$hash))throw new HttpError(409,'Mã mở ca đã dùng với nội dung khác.');$this->db->commit();return ['id'=>$input['requestId']];}$counter=json_decode($counter,true,512,JSON_THROW_ON_ERROR);if($counter['status']!=='ACTIVE')throw new HttpError(400,'Quầy đã lưu trữ.');if($this->query('SELECT shift_id FROM jingo_pos_open_shifts WHERE counter_id=?',[$input['counterId']])->fetchColumn())throw new HttpError(409,'Quầy đang có ca mở. Chốt ca cũ trước.');$this->query('INSERT INTO jingo_pos_shifts(id,counter_id,opened_by,opened_name,counter_name,opening_cash,opening_note,open_hash) VALUES (?,?,?,?,?,?,?,?)',[$input['requestId'],$input['counterId'],$actor['id'],self::actorName($actor),$counter['name'],$input['openingCash'],$input['note'],$hash]);$this->query('INSERT INTO jingo_pos_open_shifts(counter_id,shift_id) VALUES (?,?)',[$input['counterId'],$input['requestId']]);$this->audit($actor,'shift.open',$input['requestId']);$this->db->commit();return ['id'=>$input['requestId']];}catch(Throwable $e){$this->rollback($e);}
    }
    private function rollback(Throwable $e):never{if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&($e->errorInfo[1] ?? null)===1062)throw new HttpError(409,'Quầy hoặc mã thao tác đã được sử dụng. Tải lại.');throw $e;}
    private function lockShift(string $id):array
    {
        $counter=$this->query('SELECT counter_id FROM jingo_pos_shifts WHERE id=?',[$id])->fetchColumn();if($counter===false)throw new HttpError(404,'Không tìm thấy ca.');$this->query('SELECT id FROM jingo_counters WHERE id=? FOR UPDATE',[$counter])->fetchColumn();return $this->query('SELECT * FROM jingo_pos_shifts WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);
    }
    public function act(string $id,string $action,array $input,array $actor):array
    {
        if(!self::uuid($id)||!self::uuid($input['requestId'] ?? null)||!is_int($input['version'] ?? null)||$input['version']<1||$input['version']>2147483646||!in_array($action,['cash','close'],true)||array_diff(array_keys($input),$action==='close'?['requestId','version','countedCash','note']:['requestId','version','kind','amount','reference','note']))throw new HttpError(400,'Thao tác ca không hợp lệ.');$body=['requestId'=>$input['requestId'],'version'=>$input['version']];if($action==='close')$body['countedCash']=self::money($input['countedCash'] ?? null);else{if(!in_array($input['kind'] ?? null,['IN','OUT'],true))throw new HttpError(400,'Chọn loại thu chi hợp lệ.');$body['kind']=$input['kind'];$body['amount']=self::money($input['amount'] ?? null);if($body['amount']===0)throw new HttpError(400,'Số tiền thu chi phải lớn hơn 0.');$body['reference']=self::text($input['reference'] ?? null,150);}$body['note']=self::text($input['note'] ?? null,1000);$hash=self::hash(['actor'=>$actor['id'],'id'=>$id,'input'=>$body]);$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$row=$this->lockShift($id);if($action==='close'&&$row['close_request']===$body['requestId']){if(!hash_equals($row['close_hash'],$hash))throw new HttpError(409,'Mã chốt ca đã dùng với nội dung khác.');$this->db->commit();return ['id'=>$id];}if($action==='cash'){$prior=$this->query('SELECT request_hash FROM jingo_pos_cash_movements WHERE id=?',[$body['requestId']])->fetchColumn();if($prior!==false){if(!hash_equals($prior,$hash))throw new HttpError(409,'Mã thu chi đã dùng với nội dung khác.');$this->db->commit();return ['id'=>$id];}}if($row['closed_at']!==null||(int)$row['version']!==$body['version'])throw new HttpError(409,'Ca đã chốt hoặc đã thay đổi. Tải lại.');$movements=$this->movements($id);$receipts=$this->receipts($id);$opening=self::safe($row['opening_cash']);$totals=self::totals($opening,$receipts,$movements);
            if($action==='cash'){if(count($movements)>=10000)throw new HttpError(400,'Ca đã đạt 10.000 khoản thu chi. Chốt ca và mở ca mới.');if($body['kind']==='OUT'&&$body['amount']>$totals['expectedCash'])throw new HttpError(400,'Số rút chi vượt tiền mặt hiện có theo sổ ca.');self::totals($opening,$receipts,array_merge($movements,[$body]));$this->query('INSERT INTO jingo_pos_cash_movements(id,shift_id,kind,amount,reference,note,actor_id,actor_name,request_hash) VALUES (?,?,?,?,?,?,?,?,?)',[$body['requestId'],$id,$body['kind'],$body['amount'],$body['reference'],$body['note'],$actor['id'],self::actorName($actor),$hash]);$this->query('UPDATE jingo_pos_shifts SET version=version+1 WHERE id=?',[$id]);$this->audit($actor,'shift.cash.'.strtolower($body['kind']),$id);}
            else{$summary=$totals+['countedCash'=>$body['countedCash'],'difference'=>$body['countedCash']-$totals['expectedCash']];$this->query('UPDATE jingo_pos_shifts SET closed_at=UTC_TIMESTAMP(6),closed_by=?,close_request=?,close_hash=?,close_note=?,summary=?,version=version+1 WHERE id=?',[$actor['id'],$body['requestId'],$hash,$body['note'],json_encode($summary,JSON_THROW_ON_ERROR),$id]);$this->query('DELETE FROM jingo_pos_open_shifts WHERE counter_id=? AND shift_id=?',[$row['counter_id'],$id]);$this->audit($actor,'shift.close',$id);}$this->db->commit();return ['id'=>$id];}catch(Throwable $e){$this->rollback($e);}
    }
    public static function csv(array $d,bool $cash=false):string
    {
        $rows=[$cash?['Mã ca','Quầy','Mã thu/chi','Ngày ghi nhận (GMT+7)','Loại','Bổ sung (VND)','Rút/chi (VND)','Mã chứng từ','Lý do','Người ghi']:['Mã ca','Quầy','Trạng thái ca','Mở ca (GMT+7)','Chốt ca (GMT+7)','Mã khoản thu','Mã đơn','Thời gian thu (GMT+7)','Phương thức','Số tiền thu (VND)','Mã giao dịch','Mã người ghi thu']];$records=$cash?$d['movements']:$d['receipts'];if(count($records)>10000)throw new HttpError(400,'Ca vượt 10.000 dòng, chưa hỗ trợ CSV dung lượng này.');$time=static fn($v)=>$v?(new DateTimeImmutable($v,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('Y-m-d H:i:s'):'';foreach($records as $r)$rows[]=$cash?[$d['id'],$d['counterName'],$r['id'],$time($r['created_at']),$r['kind']==='IN'?'Bổ sung':'Rút/chi',$r['kind']==='IN'?$r['amount']:0,$r['kind']==='OUT'?$r['amount']:0,$r['reference'],$r['note'],$r['actor_name']]:[$d['id'],$d['counterName'],$d['closedAt']?'Đã chốt':'Đang mở',$time($d['openedAt']),$time($d['closedAt']),$r['id'],$r['code'],$time($r['created_at']),$r['method']==='CASH'?'Tiền mặt':'Chuyển khoản',$r['amount'],$r['reference'],$r['admin_id']];$cell=static function($v){$v=str_replace("\0",'',(string)$v);if(preg_match('/^[\s\x{FEFF}]*[=+@-]|^[\t\r\n]/u',$v))$v="'".$v;return '"'.str_replace('"','""',$v).'"';};return "\xEF\xBB\xBF".implode("\r\n",array_map(fn($r)=>implode(',',array_map($cell,$r)),$rows))."\r\n";
    }
}
